#!/usr/bin/env node
/**
 * slack_request.cjs - Generic Slack Web API caller.
 *
 * Usage:
 *   node slack_request.cjs <method> ['<json-body>'] [--token <token>]
 *
 * Examples:
 *   node slack_request.cjs auth.test
 *   node slack_request.cjs conversations.list '{"types":"public_channel","limit":100}'
 *   node slack_request.cjs chat.postMessage '{"channel":"C123456","text":"Hello"}'
 *
 * The token is read from --token or the SLACK_TOKEN environment variable.
 * Requires Node.js 18+ (built-in fetch).
 *
 * Output: JSON response on stdout (truncated if very large).
 * Exit code: 0 on success, 1 on failure with a clean error on stderr.
 */

const API_BASE = 'https://slack.com/api/';
const MAX_STDOUT = 8000;

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

function parseArgs(argv) {
  let method = null;
  let body = null;
  let token = process.env.SLACK_TOKEN || null;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--token') {
      token = argv[++i];
      if (token === undefined) fail('--token requires a value');
    } else if (arg === '--help' || arg === '-h') {
      process.stdout.write(
        'Usage: node slack_request.cjs <method> [json-body] [--token <token>]\n' +
          'Token source: --token flag or SLACK_TOKEN environment variable.\n',
      );
      process.exit(0);
    } else if (method === null) {
      method = arg;
    } else if (body === null) {
      body = arg;
    } else {
      fail(`Unexpected argument: ${arg}`);
    }
  }

  return { method, body, token };
}

function truncate(text, max) {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}\n... [truncated: ${text.length - max} more characters]`;
}

async function main() {
  const { method, body, token } = parseArgs(process.argv.slice(2));

  if (!method) fail('Missing method. Usage: node slack_request.cjs <method> [json-body] [--token <token>]');
  if (!token) fail('No token found. Set SLACK_TOKEN or pass --token <token>.');

  let payload = {};
  if (body !== null && body.trim() !== '') {
    try {
      payload = JSON.parse(body);
    } catch {
      fail(`Invalid JSON body: ${body}`);
    }
  }

  let response;
  try {
    response = await fetch(`${API_BASE}${method}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json; charset=utf-8',
      },
      body: JSON.stringify(payload),
    });
  } catch (err) {
    fail(`Network error: ${err.message}`);
  }

  const raw = await response.text();

  let json = null;
  try {
    json = JSON.parse(raw);
  } catch {
    fail(`Non-JSON response (HTTP ${response.status}): ${truncate(raw, 500)}`);
  }

  if (json.ok === false) {
    const detail = json.needed
      ? ` (needed: ${json.needed}, provided: ${json.provided || 'none'})`
      : '';
    fail(`Slack API error for ${method}: ${json.error}${detail}`);
  }

  if (response.status !== 200) {
    fail(`HTTP ${response.status} from ${method}: ${truncate(raw, 500)}`);
  }

  process.stdout.write(`${truncate(JSON.stringify(json, null, 2), MAX_STDOUT)}\n`);
}

main().catch((err) => fail(err.message));

#!/usr/bin/env node
/**
 * post_message.cjs - Post a message to a Slack channel, DM, or thread.
 *
 * Usage:
 *   node post_message.cjs <channel> <text> [--thread-ts <ts>] [--token <token>]
 *
 * <channel> may be a channel ID (C...), a channel name (#general),
 * or a user ID (U...) to send a direct message.
 *
 * The token is read from --token or the SLACK_TOKEN environment variable.
 * Requires Node.js 18+ (built-in fetch).
 *
 * Output: success line with message ts plus the message JSON.
 * Exit code: 0 on success, 1 on failure with a clean error on stderr.
 */

const API_BASE = 'https://slack.com/api/';

function fail(message) {
  process.stderr.write(`Failure: ${message}\n`);
  process.exit(1);
}

async function main() {
  const args = process.argv.slice(2);
  let token = process.env.SLACK_TOKEN || null;
  let threadTs = null;
  const positional = [];

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--token') {
      token = args[++i];
      if (token === undefined) fail('--token requires a value');
    } else if (args[i] === '--thread-ts') {
      threadTs = args[++i];
      if (threadTs === undefined) fail('--thread-ts requires a value');
    } else if (args[i] === '--help' || args[i] === '-h') {
      process.stdout.write(
        'Usage: node post_message.cjs <channel> <text> [--thread-ts <ts>] [--token <token>]\n',
      );
      process.exit(0);
    } else {
      positional.push(args[i]);
    }
  }

  if (positional.length < 2) fail('Missing arguments. Usage: node post_message.cjs <channel> <text>');
  if (!token) fail('No token found. Set SLACK_TOKEN or pass --token <token>.');

  const channel = positional[0];
  const text = positional.slice(1).join(' ');

  const payload = { channel, text };
  if (threadTs) payload.thread_ts = threadTs;

  let response;
  try {
    response = await fetch(`${API_BASE}chat.postMessage`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json; charset=utf-8',
      },
      body: JSON.stringify(payload),
    });
  } catch (err) {
    fail(`Network error: ${err.message}`);
  }

  const raw = await response.text();
  let json = null;
  try {
    json = JSON.parse(raw);
  } catch {
    fail(`Non-JSON response (HTTP ${response.status}): ${raw.slice(0, 300)}`);
  }

  if (!json || json.ok === false) {
    fail(`Slack API error: ${json && json.error ? json.error : `HTTP ${response.status}`}`);
  }

  process.stdout.write(
    `Success: message posted to ${json.channel} at ts ${json.ts}\n` +
      `${JSON.stringify(json.message || json, null, 2)}\n`,
  );
}

main().catch((err) => fail(err.message));
